sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var ga = new GlideAjax('ITAccessUtils');
    ga.addParam('sysparm_name', 'getManager'); // method name in Script Include
	console.log('requested by ', g_form.getValue('requested_by'));
    ga.addParam('sysparm_userSysId', g_form.getValue('requested_by'));
    ga.getXMLAnswer(function(answer) {
        if (answer) {
            g_form.setValue('manager', answer);
        } else {
            g_form.setValue('manager', '');
        }
    });

}
